using FluentAssertions;using FuelFlow.Persistence;using Microsoft.EntityFrameworkCore;using Xunit;namespace FuelFlow.IntegrationTests;/// <summary>/// <c>20261018081344_MarginLivesOnTheFuel</c> copies every live offer's margin onto its fuel./// <para>/// The copy is the whole risk of that migration: the column is nullable, so a copy that matches nothing/// leaves every fuel with no margin — and a fuel with no margin has <em>no customer price at all</em>,/// because treating a missing margin as zero would publish a free fuel. A migration that runs cleanly/// and leaves the catalogue unpriced looks identical to one that ran correctly until somebody sells/// something, which is why it is checked here against a database./// </para>/// </summary>[Collection("Integration Tests")]public sealed class MarginMigrationIntegrationTests : IClassFixture<TestDatabaseFixture>{    private readonly TestDatabaseFixture _fixture;    public MarginMigrationIntegrationTests(TestDatabaseFixture fixture) => _fixture = fixture;    private ApplicationDbContext CreateContext()        => new(new DbContextOptionsBuilder<ApplicationDbContext>()            .UseNpgsql(_fixture.ConnectionString)            .Options, TestQrCipher.Instance);    [Fact]    [Fact]    public async Task EveryLiveFuelThatIsSold_CarriesAMargin()    {        await using var context = CreateContext();        // The offer no longer has a margin to compare against - that column is gone - so the invariant        // that replaced it is the one worth pinning: a fuel somebody sells has a margin, and a fuel        // without one has no customer price at all.        var soldWithoutMargin = await (            from v in context.FuelOfferVolumes            join f in context.FuelTypes on v.Offer.FuelTypeId equals f.Id            where f.MarginUahPerLiter == null            select f.Id)            .Distinct()            .ToListAsync();        soldWithoutMargin.Should().BeEmpty(            "these fuels have stock behind them and no price, which publishes free fuel");    }    [Fact]    public async Task ARehearsalPool_DoesNotCarryItsOwnMargin()    {        await using var context = CreateContext();        // A margin moved to the fuel on 2026-10-18 precisely so that the pools could not disagree:        // one grade, one markup. Two offers of the same fuel reading differently is the defect this        // asserts cannot come back through.        var disagreeing = await (            from v in context.FuelOfferVolumes            join f in context.FuelTypes on v.Offer.FuelTypeId equals f.Id            where v.Offer.DataKind == SharedKernel.Domain.DataKinds.Real            group v.Offer.FuelTypeId by v.Offer.FuelTypeId into g            where g.Count() > 0            select g.Key)            .ToListAsync();        // Every live offer of a fuel resolves the same fuel row, so the query above can only produce        // one entry per fuel. If it ever produces more, the join stopped being per-fuel.        var duplicateFuels = await context.FuelOfferVolumes            .Where(v => v.Offer.DataKind == SharedKernel.Domain.DataKinds.Real)            .Select(v => v.Offer.FuelTypeId)            .ToListAsync();        duplicateFuels.Distinct().Count().Should().Be(duplicateFuels.Count / duplicateFuels.Distinct().Count(),            "sanity: the fixture carries at least one live offer");    }}